import{_ as s,o as i,c as a,a7 as o}from"./chunks/framework.DUCm5Bu5.js";const k=JSON.parse('{"title":"배포","description":"릴리스 빌드, Docker Compose, 백업과 롤백으로 서버를 재현 가능하게 실행합니다.","frontmatter":{"title":"배포","description":"릴리스 빌드, Docker Compose, 백업과 롤백으로 서버를 재현 가능하게 실행합니다.","updated":"2026-10-18T00:00:00.000Z"},"headers":[],"relativePath":"ko/guides/deployment.md","filePath":"ko/guides/deployment.md"}'),t={name:"ko/guides/deployment.md"};function d(l,e,p,c,n,h){return i(),a("div",null,[...e[0]||(e[0]=[o(`<p>이 페이지는 다른 사람을 위해 Bubble Fighter Fantasy를 실행하려는 경우를 다룹니다. 릴리스 빌드, 이 저장소의 Docker Compose 구성, Linux와 Windows 수동 설치, 영속 데이터와 백업, 로그, 네트워크 보안, 안전한 업그레이드와 롤백 방법을 설명합니다.</p><p><strong>대상 독자:</strong> 노트북에서 한 번 시작하는 것이 아니라 서버 프로세스를 배포하고 유지하는 운영자입니다.</p><p><strong>시작하기 전에:</strong></p><ul><li><a href="./configuration">설정</a>을 읽으십시오. 배포는 프로필 선택과 환경 변수로 이루어지며, 이 페이지는 구성 방식 자체를 반복하지 않습니다.</li><li>배포하려는 정확한 리비전을 빌드하고 검증하십시오. 릴리스 디렉터리는 경고 0개로 끝난 <code>dotnet build BubbleFighter.Fantasy.sln -c Release</code>에서 만들어집니다.</li><li>호스트를 계획하십시오. 지원되는 운영 체제와 아키텍처, 프레임워크 종속 빌드에 필요한 ASP.NET Core Runtime 10(또는 Docker), 전용 서비스 계정, 직접 소유한 데이터베이스가 필요합니다.</li><li>서비스할 모든 빌드의 클라이언트 데이터를 준비하십시오. 게임 프로필은 데이터가 없으면 활성화 단계에서 실패합니다.</li><li>백업 위치를 정하십시오. 백업은 릴리스 디렉터리 안에 두면 안 됩니다.</li></ul><h2 id="배포-전에" tabindex="-1">배포 전에 <a class="header-anchor" href="#배포-전에" aria-label="Permalink to &quot;배포 전에&quot;">​</a></h2><p>이 프로젝트는 프리릴리스입니다. 지원되는 모든 클라이언트에 대해 검증되지 않았으며, 나열된 프로필이나 통과한 자동 점검은 실제 클라이언트 호환성을 입증하지 않습니다. 프리릴리스 서비스로 운영하고, 실제 클라이언트로 테스트하며, 복원 경로를 마련해 두십시오.</p><p>이 릴리스의 지원 대상은 Windows x64, Windows ARM64, Linux x64, Linux ARM64입니다. 알려진 배포 환경은 Debian 13이며 다른 Linux 배포판은 테스트되었다고 주장하지 않습니다. 게시 스크립트는 Windows x64와 Linux x64/ARM64를 다루며, Windows ARM64는 나열된 대상으로 동일한 Host 게시 명령에 <code>-r win-arm64</code>를 지정해 게시합니다.</p><p>공개 Windows 패키지, Linux 설치 스크립트, 원클릭 Docker 설치은 아직 게시되지 않았습니다. 이 저장소에 있는 것은 소스, <code>tools/</code>의 게시 스크립트 두 개, <code>deploy/docker/</code>의 Docker 파일, Compose 구성입니다. 다른 곳의 설치 프로그램이나 이미지 레지스트리로 대체하지 마십시오.</p><p>배포에서는 네 가지 네트워크와 저장소 사항을 계획해야 합니다.</p><table tabindex="0"><thead><tr><th>사항</th><th>계획할 내용</th><th>이 릴리스의 기본값</th></tr></thead><tbody><tr><td>게임 포트</td><td>서비스하는 빌드마다 TCP 리스너 하나입니다.</td><td><code>kr-1256</code>은 7100, 레거시 <code>kr-812</code>는 7110을 사용합니다.</td></tr><tr><td>릴레이</td><td>프로필이 릴레이 리스너를 여는 빌드만 해당합니다.</td><td><code>kr-1256</code>은 7101을 사용하며, 레거시 빌드는 열지 않습니다.</td></tr><tr><td>관리 / WebUI</td><td>루프백이나 통제된 네트워크에 두고, 원격이면 인증합니다.</td><td><code>127.0.0.1:8080</code>, Bearer 토큰 없음.</td></tr><tr><td>MySQL</td><td>서버만 접근할 수 있게 하고 절대 공개하지 않습니다.</td><td><code>127.0.0.1:3306</code>, 데이터베이스 <code>bf_game_db</code>.</td></tr></tbody></table><p>클라이언트 데이터는 로컬 저장소에 준비하고 가능하면 읽기 전용으로 마운트하거나 복사하십시오. 서버는 그것을 읽기만 합니다.</p><h2 id="릴리스-디렉터리-빌드" tabindex="-1">릴리스 디렉터리 빌드 <a class="header-anchor" href="#릴리스-디렉터리-빌드" aria-label="Permalink to &quot;릴리스 디렉터리 빌드&quot;">​</a></h2><p><code>tools/</code>의 두 스크립트는 Host와 모든 플러그인을 대상 머신으로 복사할 수 있는 디렉터리에 게시합니다. 둘 다 <strong>프레임워크 종속</strong> 빌드를 만들므로 .NET 런타임을 포함하지 않으며, 대상에는 일치하는 ASP.NET Core Runtime 10이 필요합니다.</p><table tabindex="0"><thead><tr><th>스크립트</th><th>대상</th><th>설명</th></tr></thead><tbody><tr><td><code>tools/publish-windows-x64.ps1</code></td><td><code>win-x64</code></td><td>apphost가 Windows x64이고 포함된 런타임이 없는지 확인합니다.</td></tr><tr><td><code>tools/publish-linux.ps1</code></td><td><code>linux-x64</code>(기본) 또는 <code>linux-arm64</code></td><td>apphost가 요청한 아키텍처의 ELF인지 확인합니다.</td></tr></tbody></table><p>두 스크립트 모두 PowerShell 세션이 필요하며 필수 <code>-OutputPath</code>를 받습니다. 디렉터리는 없어도 되지만, 있으면 <strong>비어 있어야</strong> 합니다. 이전 릴리스가 들어 있는 디렉터리에 게시하면 그 릴리스의 런타임 파일이 남습니다. 스크립트는 덮어쓰지 않고 실패합니다.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>저장소 루트의 PowerShell 프롬프트에서:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\tools\\publish-windows</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">x64.ps1 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputPath C:\\BFF\\release</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2026</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">10</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">18</span></span></code></pre></div><p>성공하면 <code>Windows x64 framework-dependent publish ready: &lt;path&gt;</code>를 출력하고 대상에 x64 ASP.NET Core Runtime 10.0이 필요하다는 점을 알려 줍니다.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>어느 머신이든 PowerShell 7 세션에서 게시할 수 있으며 출력은 Linux 바이너리입니다.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pwsh </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">File tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">publish-linux.ps1</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">OutputPath </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">srv</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bff</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">release</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">server</span></span></code></pre></div><p>ARM64 대상에는 <code>-Runtime linux-arm64</code>를 추가하십시오. 성공하면 <code>Linux framework-dependent publish ready: &lt;path&gt; (&lt;runtime&gt;)</code>를 출력하고 InGame 플러그인이 게시되었는지 확인합니다. PowerShell은 스크립트 호스트일 뿐이며 대상 머신에는 PowerShell이 필요하지 않습니다.</p><h3 id="게시-내용" tabindex="-1">게시 내용 <a class="header-anchor" href="#게시-내용" aria-label="Permalink to &quot;게시 내용&quot;">​</a></h3><ul><li><code>BubbleFighter.Fantasy.Host</code>(apphost)와 <code>BubbleFighter.Fantasy.Host.dll</code>, Host의 종속성 및 <code>runtimeconfig.json</code>.</li><li><code>plugins/&lt;ProjectName&gt;/</code>, 플러그인 프로젝트마다 하나의 디렉터리이며 Host 옆의 기본 플러그인 루트입니다.</li><li><code>profiles/</code>, 프로필마다 하나의 디렉터리이며 <code>local.patch.yaml</code>은 포함되지 않습니다.</li><li><code>packets/</code>, 패킷 표와 <code>builds.yaml</code>.</li><li><code>bootstrap/</code>, 로더 프로필과 <code>data/level-experience.csv</code>, <code>data/locales/*.json</code>.</li></ul><p>스크립트 대신 <code>dotnet publish src/BubbleFighter.Fantasy.Host -c Release -o &lt;directory&gt;</code>를 사용할 수도 있습니다. 이는 플러그인 게시 대상과 콘텐츠 복사를 포함한 동일한 Host 게시를 수행합니다. 다만 스크립트의 빈 디렉터리 및 apphost 검사를 생략하므로 새 디렉터리를 사용하고 결과를 직접 검증하십시오. Windows ARM64에는 이 형식에 <code>-r win-arm64</code>를 붙이십시오.</p><p>복사 전에 결과를 확인하십시오. 디렉터리에는 Host 실행 파일, 플러그인마다 디렉터리가 있는 <code>plugins/</code>, 그리고 <code>profiles/</code>, <code>packets/</code>, <code>bootstrap/</code>, <code>data/</code> 디렉터리가 있어야 합니다. <code>coreclr.dll</code>, <code>libcoreclr.so</code> 같은 런타임 파일이 있으면 안 됩니다. 발견된다면 게시가 런타임을 포함한 것이므로 의도한 릴리스가 아닙니다.</p><h2 id="이-저장소의-docker-compose" tabindex="-1">이 저장소의 Docker Compose <a class="header-anchor" href="#이-저장소의-docker-compose" aria-label="Permalink to &quot;이 저장소의 Docker Compose&quot;">​</a></h2><p><code>deploy/docker/compose.yaml</code>은 이 저장소의 소스로 서버와 MySQL 데이터베이스를 시작합니다. 실행 가능한 컨테이너 구성을 얻는 가장 짧은 경로입니다.</p><ol><li><p>환경 파일을 복사하고 비어 있지 않은 데이터베이스 암호를 설정하십시오. Compose 파일은 <code>BFF_MYSQL_PASSWORD</code>를 요구하며 없으면 시작을 거부합니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">cp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env.example</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span></code></pre></div></li><li><p>Compose 파일이 찾는 위치에 클라이언트 데이터를 준비하십시오. 기본 컨테이너 프로필은 <code>kr-1256</code>이므로 저장소 옆에 <code>client-data/kr-1256/data</code>와 <code>client-data/kr-1256/dataraw</code>가 있어야 하며, <code>BFF_CLIENT_DATA_HOST</code>로 다른 위치를 지정할 수 있습니다. 게임 프로필의 데이터가 없으면 서버 컨테이너는 시작하면서 종료됩니다.</p></li><li><p>저장소 루트에서 두 서비스를 빌드하고 시작하십시오.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div></li></ol><p>시작되는 내용:</p><ul><li><code>bff</code> 서비스는 <code>deploy/docker/Dockerfile</code>에서 빌드됩니다. .NET SDK와 ASP.NET 10 이미지를 사용하는 다단계 빌드이며, 비특권 <code>bff</code> 사용자(uid 1001)로 실행되고 진입점은 <code>dotnet BubbleFighter.Fantasy.Host.dll run --profile kr-1256</code>입니다. 7100(게임), 7101(릴레이), 8080(관리 API와 WebUI)을 게시하고 Compose를 통해 저장소 <code>.env</code>를 읽습니다. 게임과 릴레이 리스너는 <code>BFF_BIND_HOST</code>를 사용하며 예제 <code>.env</code>가 이를 <code>0.0.0.0</code>으로 설정하므로 해당 게시 포트는 접근할 수 있습니다. 반면 관리 행은 <code>BFF_ADMIN_HOST</code>에 바인딩하고 기본값이 <code>127.0.0.1</code>이므로, 컨테이너 안에서 API와 WebUI는 루프백에만 수신합니다. 따라서 <code>.env</code>에 <code>BFF_ADMIN_HOST=0.0.0.0</code>을 추가하지 않으면 게시된 8080 포트로 접근할 수 없습니다.</li><li><code>mysql</code> 서비스는 MySQL 8.4를 실행하고 <code>BFF_MYSQL_DATABASE</code>, <code>BFF_MYSQL_USER</code>, <code>BFF_MYSQL_PASSWORD</code>로 데이터베이스와 계정을 만들며, 호스트에 <code>\${BFF_MYSQL_PORT:-3306}</code>을 게시하고 데이터를 <code>mysql-data</code> 볼륨에 보관합니다. 서버는 상태 확인이 통과한 뒤 시작하며 컨테이너 네트워크 안에서 <code>BFF_MYSQL_HOST=mysql</code>을 받습니다.</li><li>클라이언트 데이터는 <code>/app/client-data</code>에 읽기 전용으로 마운트되고, 데이터베이스 상태는 <code>mysql-data</code> 볼륨에 있습니다. 서버 자체 로그는 컨테이너 안에 기록되며 이 Compose 파일은 호스트로 보존하지 않습니다.</li></ul><p>잘 동작하는지 확인하십시오. 기본 루프백 관리 바인딩에서는 호스트의 <code>curl http://127.0.0.1:8080/health</code>가 컨테이너에 도달하지 않습니다. 호스트에서 확인하려면 시작 전에 <code>.env</code>에 <code>BFF_ADMIN_HOST=0.0.0.0</code>을 추가하고, 포트를 여는 전에 <code>BFF_ADMIN_TOKEN</code>을 설정하십시오. 응답은 <code>status</code> 필드가 있는 JSON입니다. 관리를 루프백에 유지한다면 대신 서버 콘솔 출력으로 준비 상태를 확인하십시오. 콘솔은 다음 명령으로 따를 수 있습니다.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deploy/docker/compose.yaml</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -f</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bff</span></span></code></pre></div><p><code>docker compose -f deploy/docker/compose.yaml down</code>으로 두 서비스를 중지하십시오. 데이터베이스 볼륨은 유지됩니다. <code>down -v</code>는 볼륨도 삭제하므로 데이터베이스를 버리려는 것이 아니라면 <code>-v</code>를 사용하지 마십시오.</p><p>이 Compose 파일을 외부에 노출하기 전에 검토하십시오. MySQL을 호스트에 게시하고, Docker 기본 로그 처리(크기 제한 없음)를 그대로 두며, 기본 게임 프로필을 실행합니다. 개발 스타일 구성이며 강화된 운영 템플릿이 아닙니다.</p><h2 id="linux-릴리스-루트에서-외부-데이터베이스와-함께-docker-사용" tabindex="-1">Linux 릴리스 루트에서 외부 데이터베이스와 함께 Docker 사용 <a class="header-anchor" href="#linux-릴리스-루트에서-외부-데이터베이스와-함께-docker-사용" aria-label="Permalink to &quot;Linux 릴리스 루트에서 외부 데이터베이스와 함께 Docker 사용&quot;">​</a></h2><p><code>deploy/docker/compose.external-db.yaml</code>은 다른 산출물입니다. 이미 데이터베이스가 실행 중인 Linux 호스트의 릴리스 루트를 위한 템플릿입니다. 대상 머신에서 다음 배치를 만드십시오.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;release-root&gt;/</span></span>
<span class="line"><span>  compose.yaml     deploy/docker/compose.external-db.yaml 복사본</span></span>
<span class="line"><span>  Dockerfile       deploy/docker/Dockerfile.published 복사본</span></span>
<span class="line"><span>  .env             BFF_RELEASE를 포함한 배포 변수</span></span>
<span class="line"><span>  server/          프레임워크 종속 Linux 게시 출력</span></span>
<span class="line"><span>  logs/            컨테이너가 기록</span></span>
<span class="line"><span>  client-data/     선택 사항. 또는 BFF_CLIENT_DATA_HOST로 다른 위치 지정</span></span></code></pre></div><ol><li><p><code>tools/publish-linux.ps1</code>로 릴리스 출력을 <code>server/</code>에 게시하십시오. 게시 디렉터리는 비어 있어야 하므로 다른 내용을 복사하기 전에 <code>server/</code>에 게시하십시오.</p></li><li><p><code>deploy/docker/compose.external-db.yaml</code>을 <code>&lt;release-root&gt;/compose.yaml</code>로, <code>deploy/docker/Dockerfile.published</code>를 <code>&lt;release-root&gt;/Dockerfile</code>로 복사하십시오.</p></li><li><p><code>&lt;release-root&gt;/.env</code>를 만드십시오. <code>BFF_RELEASE</code>(이미지 태그)와 로컬 데이터베이스의 MySQL 값을 설정해야 합니다. 주소와 토큰을 검토하십시오. <code>BFF_BIND_HOST</code>, <code>BFF_MYSQL_HOST</code>, 관리 주소는 템플릿이 강제로 설정합니다.</p></li><li><p><code>&lt;release-root&gt;</code>에서 시작하십시오.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --build</span></span></code></pre></div></li></ol><p>이 템플릿이 제공하는 것: <code>server/</code>에서 빌드한 <code>bf-fantasy:&lt;release&gt;</code> 이미지, 호스트 네트워킹(따라서 <code>.env</code>에 구성된 게임, 릴레이, 관리 포트가 그대로 사용되고 <code>127.0.0.1</code>의 데이터베이스에 접근 가능), 작은 쓰기 가능 <code>/tmp</code>가 있는 읽기 전용 컨테이너 파일 시스템, 모든 capability 제거, <code>no-new-privileges</code>, 30초 중지 유예 기간, 중지하지 않는 한 재시작, 패킷 로그 파일을 위한 <code>./logs</code>를 <code>/app/logs</code>에 마운트, 클라이언트 데이터를 <code>/app/client-data</code>에 읽기 전용 마운트, 10 MB 파일 5개로 제한된 json-file 로깅.</p><p>이 Dockerfile 변형은 이미지를 <code>run --profile all</code>로 시작하므로 릴리스는 기동된 모든 빌드를 각자의 포트로 서비스하며 해당 빌드들의 클라이언트 데이터가 필요합니다. 하나의 빌드만 서비스하려면 운영자가 관리하는 Dockerfile 복사본에서 <code>CMD</code>를 바꾸십시오.</p><p><code>docker compose down</code>은 서비스를 중지하고 <code>logs/</code> 디렉터리를 유지합니다. 데이터베이스는 이 템플릿이 관리하지 않으므로 자체 도구로 백업하고 업그레이드하십시오. <code>deploy/docker/Dockerfile.published</code>는 이 배치가 빌드에 사용하는 저장소 파일이며, 어떤 이미지도 레지스트리에 게시되지 않으므로 이미지는 항상 대상 머신에서 빌드됩니다.</p><h2 id="linux-수동-배포" tabindex="-1">Linux 수동 배포 <a class="header-anchor" href="#linux-수동-배포" aria-label="Permalink to &quot;Linux 수동 배포&quot;">​</a></h2><p>컨테이너를 원하지 않을 때 사용하는 경로입니다. Linux 게시 출력을 대상으로 복사하고 Host를 직접 실행하십시오.</p><ol><li><p><code>tools/publish-linux.ps1</code>로 게시하고 출력을 <code>&lt;release-root&gt;</code>로 복사하십시오. 게시의 디렉터리 배치는 그대로 유지하십시오.</p></li><li><p>전용 서비스 계정(예: <code>bff</code>)을 만들고 릴리스 디렉터리를 소유하게 하되 대화형 로그인은 허용하지 마십시오. Host는 <code>profiles/</code>, <code>packets/</code>, <code>bootstrap/</code>, <code>plugins/</code>, <code>data/</code>만 읽으면 되고, <code>logs/</code>를 쓸 수 있는 작업 디렉터리와 SQLite를 사용할 경우 저장 파일을 둘 쓰기 가능한 위치가 필요합니다.</p></li><li><p>복사 과정에서 실행 권한이 사라졌다면 apphost를 실행 가능하게 만드십시오: <code>chmod +x BubbleFighter.Fantasy.Host</code>.</p></li><li><p>프로세스 환경에 배포 변수를 제공하십시오. 릴리스 디렉터리에는 저장소 표식이 없으므로 그 옆에 둔 <code>.env</code>는 Host가 <strong>읽지 않습니다</strong>. <code>.env</code> 로드 규칙은 체크아웃 안에서만 적용됩니다. 서비스 관리자나 셸이 읽는 환경 파일을 사용하십시오. 예:</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -a</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">release-roo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/deployment.env</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> +a</span></span></code></pre></div><p>이 파일에는 <code>.env.example</code>과 같은 <code>KEY=VALUE</code> 항목이 들어가며 실제 MySQL 암호, 공개 주소, 관리 토큰을 채웁니다.</p></li><li><p>릴리스 루트로 이동해 Host를 포그라운드로 시작하십시오.</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">release-roo</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">t</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./BubbleFighter.Fantasy.Host</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --profile</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> kr-1256</span></span></code></pre></div><p>작업 디렉터리가 중요합니다. <code>profiles</code>, <code>packets</code>, <code>client-data</code>, <code>logs</code>가 이를 기준으로 확인됩니다. <code>Ctrl+C</code> 또는 SIGTERM은 정상 종료를 요청하며 콘솔은 <code>Shutdown complete.</code>로 끝납니다.</p></li><li><p>저장소는 서비스 유닛을 제공하지 않습니다. 장기 운영 시에는 직접 관리하는 서비스 관리자(예: systemd 서비스) 아래에서 Host를 실행하고, 작업 디렉터리를 <code>&lt;release-root&gt;</code>로 설정하며 환경 파일로 변수를 제공하십시오. 서비스 계정은 비특권으로 유지하고 릴리스, 로그 디렉터리, 사용하는 경우 SQLite 파일에만 접근 권한을 주십시오.</p></li></ol><p>호스트에서 <code>curl http://127.0.0.1:8080/health</code>로 확인하고 아래의 리스닝 포트 점검을 사용하십시오. 서비스 관리자의 SIGTERM 또는 포그라운드의 <code>Ctrl+C</code>로 중지하십시오.</p><h2 id="windows-수동-배포" tabindex="-1">Windows 수동 배포 <a class="header-anchor" href="#windows-수동-배포" aria-label="Permalink to &quot;Windows 수동 배포&quot;">​</a></h2><ol><li><p><code>tools/publish-windows-x64.ps1</code>로 게시하고 출력을 배포 디렉터리로 복사하십시오.</p></li><li><p>시작 전에 프로세스에 배포 변수를 설정하십시오. 예를 들어 프로세스를 소유할 PowerShell 세션에서:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BFF_MYSQL_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;127.0.0.1&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BFF_MYSQL_PASSWORD </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;your-database-password&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BFF_PUBLIC_HOST </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;public-address-clients-use&gt;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">BFF_ADMIN_TOKEN </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;long-random-token&gt;&#39;</span></span></code></pre></div><p>Linux와 마찬가지로 릴리스 디렉터리에 복사한 <code>.env</code>는 읽히지 않습니다. Host는 저장소 루트를 찾을 수 있을 때만 저장소 <code>.env</code>를 로드합니다.</p></li><li><p>상대 경로 <code>profiles</code>, <code>packets</code>, <code>client-data</code>, <code>logs</code>가 그곳에서 확인되도록 릴리스 디렉터리에서 Host를 시작하십시오.</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Set-Location</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> C:\\BFF\\</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">release</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">BubbleFighter.Fantasy.Host.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> run </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">profile kr</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1256</span></span></code></pre></div></li><li><p>방화벽에서 계획한 게임, 릴레이, 관리 포트만 허용하십시오. 관리 포트는 신뢰할 수 있는 네트워크에서만 접근 가능하게 하고 MySQL은 공용 인터페이스에서 멀리 두십시오.</p></li><li><p>이 저장소에는 Windows 서비스 래퍼가 없습니다. 머신과 함께 시작해야 한다면 직접 관리하는 서비스 관리자 아래에서 실행 파일을 실행하고 서비스 계정은 비특권으로 유지하십시오.</p></li></ol><p><code>Invoke-RestMethod http://127.0.0.1:8080/health</code>로 확인하십시오. <code>status</code> 필드가 있는 JSON을 반환합니다. <code>Ctrl+C</code>로 중지하며, 플랫폼이 신호를 제공하는 경우 Host는 SIGTERM과 SIGINT도 처리합니다.</p><h2 id="영속-데이터와-백업" tabindex="-1">영속 데이터와 백업 <a class="header-anchor" href="#영속-데이터와-백업" aria-label="Permalink to &quot;영속 데이터와 백업&quot;">​</a></h2><table tabindex="0"><thead><tr><th>데이터</th><th>위치</th><th>업그레이드 전 백업</th></tr></thead><tbody><tr><td>게임 및 계정 데이터</td><td>MySQL 데이터베이스 <code>bf_game_db</code>, 또는 SQLite 저장 파일 하나.</td><td>예; 모든 업그레이드마다.</td></tr><tr><td>클라이언트 데이터</td><td><code>client-data/&lt;build&gt;/</code> 아래의 읽기 전용 파일.</td><td>한 번, 또는 클라이언트 복사본을 바꿀 때.</td></tr><tr><td>구성과 비밀 정보</td><td>Compose <code>.env</code> 또는 서비스 관리자의 환경 파일.</td><td>예; 안전하게 보관.</td></tr><tr><td>로그와 패킷 로그</td><td>작업 디렉터리의 <code>logs/&lt;date&gt;/</code>, 또는 컨테이너 경로.</td><td>선택; 정책에 따라 회전 및 보존.</td></tr><tr><td>이전 릴리스</td><td>별도 디렉터리.</td><td>롤백 기간이 끝날 때까지 보관.</td></tr></tbody></table><p>데이터베이스, 그 백업, SQLite 저장 파일은 릴리스 디렉터리 밖에 두십시오. 릴리스는 교체되기 때문입니다. MySQL은 서버가 중지되었거나 쓰기가 없을 때 데이터베이스 자체 백업 도구(예: 논리 덤프 <code>mysqldump</code> 또는 일관된 스토리지 스냅샷)를 사용하십시오. SQLite는 먼저 서버를 중지한 뒤 단일 저장 파일을 복사하십시오. 서버가 쓰는 중인 SQLite 파일을 복사하지 마십시오.</p><p>백업에 의존하기 전에 별도 인스턴스에서 복원을 테스트하십시오. 데이터베이스를 복원하거나 저장 파일을 복사하고, 그것으로 릴리스를 시작해 <code>/health</code>, 플러그인 행 상태, 클라이언트 흐름을 확인하십시오. 한 번도 복원해 보지 않은 백업은 검증된 백업이 아닙니다.</p><p>클라이언트 데이터는 상태가 아니라 입력입니다. 서버는 읽기만 하고 Docker 구성은 읽기 전용으로 마운트하므로 릴리스를 교체해도 바뀌지 않습니다.</p><h2 id="로그" tabindex="-1">로그 <a class="header-anchor" href="#로그" aria-label="Permalink to &quot;로그&quot;">​</a></h2><p>서버는 콘솔에 로그를 기록합니다. 각 줄은 한 줄이며 UTC 타임스탬프를 가집니다. 수준은 <code>BFF_LOG_LEVEL</code> 또는 <code>--log-level</code>에서 오고 기본값은 <code>Information</code>입니다. 정상 시작은 활성화된 각 행, 각 리스너의 수신 주소, 준비 후 <code>Server started with &lt;n&gt; active row(s).</code>를 보고합니다. 정상 종료는 <code>Shutdown complete.</code>로 끝납니다.</p><p>진단 행은 패킷 로그 파일도 기록합니다. 이는 콘솔과 별개이며 패킷과 연결 이벤트마다 한 줄입니다.</p><ul><li>기본 경로는 작업 디렉터리 기준 <code>logs/{date}/packets_{timestamp}.log</code>입니다. 프로필이 이름을 덮어씁니다. <code>kr-812</code>는 <code>packets-kr-812_{timestamp}.log</code>, <code>all</code> 프로필은 <code>packets-all_{timestamp}.log</code>를 씁니다.</li><li>각 파일은 10 MiB에서 <code>.1</code>로 회전하며 <code>{date}</code>가 바뀌면 새 파일을 시작합니다. 기본적으로 설정된 파일 이름 패턴당 최대 100개 파일을 유지하고, 싱크가 시작할 때 더 오래된 파일을 삭제합니다. 파일 이름 시간대는 기본값이 China Standard Time입니다.</li><li>쓰기는 경계가 정해진 큐(기본 32768개 레코드)를 거치며 종료 시 최대 10초 동안 플러시합니다. 오버플로는 <code>packet-log-overflow</code>로 보고되며 게임플레이 패킷을 절대 버리지 않습니다.</li><li>전체 패킷 기록기는 기본적으로 꺼져 있습니다. <code>BFF_PACKET_CAPTURE=true</code>를 설정하면 활성화되며 같은 <code>logs/</code> 트리 아래에 별도 JSONL 패킷 파일을 씁니다.</li></ul><p>패킷 로그 줄과 캡처에는 플레이어와 연결 데이터가 포함될 수 있습니다. <code>logs</code> 디렉터리를 민감 정보로 취급하고 평소의 보존 정책을 적용하십시오. Docker 구성에서 릴리스 루트 템플릿은 <code>./logs</code>를 마운트해 패킷 파일을 호스트에 보존하며, 콘솔 출력은 컨테이너의 json-file 로그로 가서 10 MB 파일 5개로 제한됩니다.</p><h2 id="관리-및-네트워크-보안" tabindex="-1">관리 및 네트워크 보안 <a class="header-anchor" href="#관리-및-네트워크-보안" aria-label="Permalink to &quot;관리 및 네트워크 보안&quot;">​</a></h2><ul><li>관리 리스너는 기본적으로 <code>127.0.0.1:8080</code>에 바인딩합니다. <code>/health</code>와 WebUI 파일은 토큰 없이 접근할 수 있고, 토큰이 설정되면 모든 <code>/api</code> 경로에 <code>Authorization: Bearer &lt;BFF_ADMIN_TOKEN&gt;</code>이 필요합니다. 토큰이 비어 있으면 관리 인증이 없습니다.</li><li>관리 포트를 루프백 밖으로 노출하기 전에 길고 무작위인 <code>BFF_ADMIN_TOKEN</code>을 설정하고 원본 네트워크를 제한하십시오. 제한할 수 없다면 루프백에 두고 직접 관리하는 터널이나 역방향 프록시를 사용하십시오.</li><li>방화벽에서는 선택한 프로필이 서비스하는 게임 및 릴레이 포트만 여십시오. 관리 포트나 MySQL을 공용 인터페이스에 게시하지 마십시오.</li><li>전용 데이터베이스 계정을 사용하고 MySQL 포트를 루프백이나 사설 네트워크에 두며, 데이터베이스 관리자 계정을 서버에 재사용하지 마십시오.</li><li>비밀 정보는 배포 로컬 <code>.env</code>(Compose) 또는 서비스 관리자 환경 파일(수동)에 보관하십시오. 권한을 제한하고 절대 커밋하지 마십시오. <code>--dump-config</code>는 보간된 비밀 정보를 보여 주므로 그 출력을 공개 보고서에 첨부하지 마십시오.</li><li>클라이언트 데이터, 패킷 로그, 캡처를 공개하지 마십시오. 전용 클라이언트 파일과 플레이어 데이터가 포함될 수 있습니다.</li></ul><h2 id="업그레이드와-롤백" tabindex="-1">업그레이드와 롤백 <a class="header-anchor" href="#업그레이드와-롤백" aria-label="Permalink to &quot;업그레이드와 롤백&quot;">​</a></h2><p>업그레이드는 나란히 설치하는 방식입니다. 새 릴리스를 새 디렉터리에 설치하고 이전 릴리스를 유지한 뒤, 한 프로세스를 중지하고 다른 프로세스를 시작해 전환합니다.</p><ol><li>유지 관리 시간을 공지하고 새 작업 수락을 중단하십시오. 경기를 끝내거나 의도적으로 종료한 뒤 SIGTERM 또는 <code>Ctrl+C</code>로 서버를 정상 중지하고 <code>Shutdown complete.</code>를 기다리십시오.</li><li>위에서 설명한 대로 데이터베이스를 백업하고 실행 중인 정확한 릴리스 디렉터리와 구성을 기록하십시오.</li><li>새 릴리스를 새 빈 디렉터리에 게시하십시오. 이전 릴리스 위에 게시하지 마십시오.</li><li>배포 변수와 클라이언트 데이터를 복사하거나 재사용하십시오. 클라이언트를 업데이트하지 않는 한 클라이언트 데이터는 릴리스 간에 바뀌지 않습니다.</li><li>새 디렉터리에서 새 릴리스를 시작하고 검증하십시오. <code>/health</code>, 플러그인 행 상태, 리스닝 포트, 저장소 연결 줄, 콘솔 오류 없음.</li><li>롤백이 더 이상 필요하지 않을 때까지 이전 릴리스 디렉터리와 업그레이드 전 백업을 보관하십시오.</li></ol><p>롤백하려면 새 릴리스를 중지하고 이전 릴리스 디렉터리를 같은 구성으로 시작하며, 새 릴리스가 스키마를 바꿨다면 업그레이드 전 데이터베이스 백업을 복원하십시오. 바이너리만 롤백하는 것은 보장되지 않습니다. MySQL 마이그레이션은 영속성 행이 활성화될 때 자동으로 적용되며 순방향 전용입니다. 서버에는 다운그레이드 경로가 없으므로 이전 바이너리는 새 릴리스가 이미 마이그레이션한 데이터베이스에서 실행되지 못할 수 있습니다. 안전한 롤백 조합은 이전 릴리스와 업그레이드 전에 받은 백업입니다.</p><h2 id="배포-후-점검" tabindex="-1">배포 후 점검 <a class="header-anchor" href="#배포-후-점검" aria-label="Permalink to &quot;배포 후 점검&quot;">​</a></h2><ul><li>[ ] <code>GET /health</code>가 <code>status</code>가 <code>ok</code>인 JSON을 반환합니다.</li><li>[ ] <code>GET /api/plugins</code>(Bearer 토큰 사용) 또는 WebUI 목록에 모든 예상 행이 실패 상태 없이 표시됩니다.</li><li>[ ] 호스트의 리스닝 포트가 계획과 일치합니다. Linux는 <code>ss -ltn</code>, PowerShell은 <code>Get-NetTCPConnection -State Listen</code>으로 확인합니다.</li><li>[ ] 콘솔에 저장소 연결 줄이 표시됩니다(MySQL 연결됨 또는 SQLite 활성).</li><li>[ ] 서비스하는 모든 게임 빌드의 <code>clientdata</code> 행이 실패가 아니라 활성 상태입니다.</li><li>[ ] 로그 수준이 운영에 적절하고, 패킷 로그가 예상된다면 패킷 로그 디렉터리가 쓰기 가능하며 증가합니다.</li><li>[ ] 백업을 받았고 테스트 인스턴스에서 최소 한 번 복원했습니다.</li><li>[ ] 소유자가 실제 클라이언트로 테스트했습니다. 자동 점검과 나열된 프로필은 클라이언트 수용이 아닙니다.</li></ul><h2 id="문제가-생기면" tabindex="-1">문제가 생기면 <a class="header-anchor" href="#문제가-생기면" aria-label="Permalink to &quot;문제가 생기면&quot;">​</a></h2><ul><li><strong>컨테이너가 즉시 종료됩니다.</strong> 기본 프로필이 게임 프로필이고 클라이언트 데이터가 없습니다. <code>client-data/&lt;build&gt;/data</code> 또는 <code>dataraw</code>를 추가하거나 클라이언트 데이터가 필요 없는 프로필을 실행하십시오.</li><li><strong>서버가 MySQL에 연결하지 못합니다.</strong> 주소, 포트, 계정, 데이터베이스 이름을 확인하십시오. <code>BFF_MYSQL_DATABASE</code>는 <code>bf_game_db</code>여야 합니다. 릴리스 디렉터리는 로컬 <code>.env</code>를 읽지 않으므로 프로세스 환경의 변수를 확인하십시오.</li><li><strong><code>/api</code>가 401을 반환합니다.</strong> 관리 토큰이 설정되어 있는데 요청에 일치하는 Bearer 토큰이 없습니다.</li><li><strong>포트가 이미 사용 중입니다.</strong> 충돌 프로세스를 중지하거나 빌드별 포트 변수를 바꾼 뒤 다시 시작하십시오.</li></ul><p>순서대로 확인하는 목록은 <a href="./troubleshooting">문제 해결</a>을 참고하십시오.</p><h2 id="다음-단계" tabindex="-1">다음 단계 <a class="header-anchor" href="#다음-단계" aria-label="Permalink to &quot;다음 단계&quot;">​</a></h2><p><a href="./configuration">설정</a>에서 위에 사용된 프로필, 포트, 저장소 키를, <a href="./plugins">플러그인</a>에서 행의 활성화와 재로드 방식을 확인하십시오.</p>`,73)])])}const g=s(t,[["render",d]]);export{k as __pageData,g as default};
